FILES = {}

FILES['backend/prisma/schema.prisma'] = '// Schema Prisma - Application de suivi de camps d\'entrainement\n// Par defaut : SQLite (aucune installation requise).\n// Pour passer sur PostgreSQL en production, remplacer le provider ci-dessous\n// par "postgresql" et adapter DATABASE_URL dans .env\n\ngenerator client {\n  provider = "prisma-client-js"\n}\n\ndatasource db {\n  provider = "sqlite"\n  url      = env("DATABASE_URL")\n}\n\n// Note : pas d\'enum Prisma ici (ExerciseUnit / RecurrenceType) car SQLite ne supporte pas\n// les enums natifs. Les valeurs autorisees ("REPS"/"SECONDS", "DAILY"/"WEEKLY"/"EVERY_N_DAYS")\n// sont validees cote API avec zod.\n\nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  passwordHash   String\n  name           String\n  weightKg       Float?\n  heightCm       Float?\n  birthDate      DateTime?\n  sex            String?  // "F" | "M" | "AUTRE" | null, libre / optionnel\n  createdAt      DateTime @default(now())\n\n  memberships    CampMembership[]\n  createdCamps   Camp[]            @relation("CampCreator")\n  createdExos    Exercise[]        @relation("ExerciseCreator")\n  logs           ExerciseLog[]\n  subscriptions  PushSubscription[]\n  badges         UserBadge[]\n  campMessages   CampMessage[]\n  sentMessages   DirectMessage[]   @relation("MessageSender")\n  receivedMessages DirectMessage[] @relation("MessageRecipient")\n}\n\nmodel Exercise {\n  id          String       @id @default(cuid())\n  name        String\n  description String?\n  unit        String       // "REPS" ou "SECONDS"\n  isCustom    Boolean      @default(false)\n  createdById String?\n  createdBy   User?        @relation("ExerciseCreator", fields: [createdById], references: [id])\n  createdAt   DateTime     @default(now())\n\n  campExercises CampExercise[]\n  logs          ExerciseLog[]\n}\n\nmodel Camp {\n  id          String    @id @default(cuid())\n  name        String\n  code        String    @unique\n  createdById String\n  createdBy   User      @relation("CampCreator", fields: [createdById], references: [id])\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime  @default(now())\n\n  exercises CampExercise[]\n  members   CampMembership[]\n  logs      ExerciseLog[]\n  messages  CampMessage[]\n}\n\n// Consigne d\'un exercice au sein d\'un camp : definie UNIQUEMENT par le createur du camp\n// (la "casquette entraineur"). Tous les membres suivent la meme consigne.\nmodel CampExercise {\n  id             String   @id @default(cuid())\n  campId         String\n  exerciseId     String\n  description    String?  // court descriptif/consigne redige par le createur du camp\n  targetSets     Int      @default(3)\n  targetMode     String   @default("FIXED") // "FIXED" (objectif chiffre) ou "MAX" (a fond, sans cible fixe)\n  targetValue    Int?     // nombre de repetitions OU de secondes vise (voir Exercise.unit) ; inutilise si targetMode = MAX\n  recurrenceType String   @default("DAILY") // "DAILY" | "WEEKLY" | "EVERY_N_DAYS"\n  daysOfWeek     String?  // JSON array ex: "[1,3,5]" (0=dimanche ... 6=samedi), utilise si WEEKLY\n  intervalDays   Int?     // utilise si EVERY_N_DAYS\n  startDate      DateTime @default(now())\n\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise Exercise @relation(fields: [exerciseId], references: [id])\n  logs     ExerciseLog[]\n\n  @@unique([campId, exerciseId])\n}\n\nmodel CampMembership {\n  id       String   @id @default(cuid())\n  userId   String\n  campId   String\n  joinedAt DateTime @default(now())\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campId])\n}\n\nmodel ExerciseLog {\n  id         String   @id @default(cuid())\n  userId     String\n  campId     String\n  exerciseId String\n  date       DateTime // jour concerne (heure normalisee a minuit)\n  setsDone   Int\n  valueDone  Int      // repetitions ou secondes realisees (moyenne/estimation par serie, cf notes)\n  completed  Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp         Camp          @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise     Exercise      @relation(fields: [exerciseId], references: [id])\n  campExercise CampExercise? @relation(fields: [campId, exerciseId], references: [campId, exerciseId])\n\n  @@unique([userId, campId, exerciseId, date])\n}\n\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel UserBadge {\n  id        String   @id @default(cuid())\n  userId    String\n  badgeKey  String   // identifiant du badge, voir src/utils/badges.ts pour le catalogue\n  earnedAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, badgeKey])\n}\n\n// Discussion de groupe entre les membres d\'un camp\nmodel CampMessage {\n  id        String   @id @default(cuid())\n  campId    String\n  userId    String\n  body      String\n  createdAt DateTime @default(now())\n\n  camp Camp @relation(fields: [campId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Message prive entre deux utilisateurs (reserve aux personnes qui partagent au moins un camp)\nmodel DirectMessage {\n  id          String   @id @default(cuid())\n  senderId    String\n  recipientId String\n  body        String\n  createdAt   DateTime @default(now())\n\n  sender    User @relation("MessageSender", fields: [senderId], references: [id], onDelete: Cascade)\n  recipient User @relation("MessageRecipient", fields: [recipientId], references: [id], onDelete: Cascade)\n}\n'
FILES['backend/src/index.ts'] = 'import "dotenv/config";\nimport express from "express";\nimport cors from "cors";\n\nimport authRoutes from "./routes/auth";\nimport userRoutes from "./routes/users";\nimport exerciseRoutes from "./routes/exercises";\nimport campRoutes from "./routes/camps";\nimport campExerciseRoutes from "./routes/campExercises";\nimport todayRoutes from "./routes/today";\nimport logRoutes from "./routes/logs";\nimport progressRoutes from "./routes/progress";\nimport pushRoutes from "./routes/push";\nimport badgeRoutes from "./routes/badges";\nimport campMessageRoutes from "./routes/campMessages";\nimport messageRoutes from "./routes/messages";\nimport { initPush, scheduleReminders } from "./services/notifications";\n\nconst app = express();\n\napp.use(cors({ origin: process.env.FRONTEND_URL || "*" }));\napp.use(express.json());\n\napp.get("/api/health", (_req, res) => res.json({ status: "ok" }));\n\napp.use("/api/auth", authRoutes);\napp.use("/api/users", userRoutes);\napp.use("/api/exercises", exerciseRoutes);\napp.use("/api/camps", campRoutes);\napp.use("/api/camp-exercises", campExerciseRoutes);\napp.use("/api/today", todayRoutes);\napp.use("/api/logs", logRoutes);\napp.use("/api/progress", progressRoutes);\napp.use("/api/push", pushRoutes);\napp.use("/api/badges", badgeRoutes);\napp.use("/api/camps", campMessageRoutes);\napp.use("/api/messages", messageRoutes);\n\n// Gestion d\'erreur generique (evite qu\'une exception fasse planter le process)\napp.use((err: any, _req: express.Request, res: express.Response, _next: express.NextFunction) => {\n  console.error(err);\n  res.status(500).json({ error: "Erreur interne du serveur." });\n});\n\nconst port = Number(process.env.PORT || 4000);\n\ninitPush();\nscheduleReminders();\n\napp.listen(port, () => {\n  console.log(`API demarree sur http://localhost:${port}`);\n});\n'
FILES['backend/src/routes/campExercises.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst recurrenceSchema = z.discriminatedUnion("recurrenceType", [\n  z.object({ recurrenceType: z.literal("DAILY") }),\n  z.object({ recurrenceType: z.literal("WEEKLY"), daysOfWeek: z.array(z.number().min(0).max(6)).min(1) }),\n  z.object({ recurrenceType: z.literal("EVERY_N_DAYS"), intervalDays: z.number().min(1) }),\n]);\n\nconst targetSchema = z.discriminatedUnion("targetMode", [\n  z.object({ targetMode: z.literal("FIXED"), targetValue: z.number().min(1) }),\n  z.object({ targetMode: z.literal("MAX"), targetValue: z.number().min(1).optional() }),\n]);\n\nconst updateSchema = z\n  .object({\n    campId: z.string(),\n    exerciseId: z.string(),\n    description: z.string().max(500).optional().nullable(),\n    targetSets: z.number().min(1),\n  })\n  .and(targetSchema)\n  .and(recurrenceSchema);\n\n// Met a jour la consigne d\'un exercice au sein d\'un camp : reserve au createur du camp\n// (la "casquette entraineur"). Les autres membres ne peuvent que consulter.\nrouter.put("/", async (req: AuthRequest, res) => {\n  const parsed = updateSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const data = parsed.data;\n\n  const camp = await prisma.camp.findUnique({ where: { id: data.campId } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur du camp peut definir les consignes des exercices." });\n  }\n\n  const campExercise = await prisma.campExercise.findUnique({\n    where: { campId_exerciseId: { campId: data.campId, exerciseId: data.exerciseId } },\n  });\n  if (!campExercise) return res.status(400).json({ error: "Cet exercice ne fait pas partie du camp." });\n\n  const updated = await prisma.campExercise.update({\n    where: { campId_exerciseId: { campId: data.campId, exerciseId: data.exerciseId } },\n    data: {\n      description: data.description ?? null,\n      targetSets: data.targetSets,\n      targetMode: data.targetMode,\n      targetValue: data.targetMode === "FIXED" ? data.targetValue : data.targetValue ?? null,\n      recurrenceType: data.recurrenceType,\n      daysOfWeek: data.recurrenceType === "WEEKLY" ? JSON.stringify(data.daysOfWeek) : null,\n      intervalDays: data.recurrenceType === "EVERY_N_DAYS" ? data.intervalDays : null,\n    },\n    include: { exercise: true },\n  });\n\n  res.json(updated);\n});\n\nexport default router;\n'
FILES['backend/src/routes/today.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { isDueOnDate, toDayStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Renvoie, pour aujourd\'hui, tous les exercices dus (tous camps dont l\'utilisateur est membre)\n// selon la consigne definie par le createur de chaque camp, avec l\'info si deja fait ou non.\nrouter.get("/", async (req: AuthRequest, res) => {\n  const today = toDayStart(new Date());\n\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    include: {\n      camp: {\n        include: { exercises: { include: { exercise: true } } },\n      },\n    },\n  });\n\n  const campExercises = memberships.flatMap((m) =>\n    m.camp.exercises.map((ce) => ({ ...ce, camp: m.camp }))\n  );\n\n  // On ne propose que les exercices dont le camp est en cours (entre sa date de debut et de fin, si definies)\n  const withinCampDates = campExercises.filter((ce) => {\n    if (ce.camp.startDate && today.getTime() < toDayStart(ce.camp.startDate).getTime()) return false;\n    if (ce.camp.endDate && today.getTime() > toDayStart(ce.camp.endDate).getTime()) return false;\n    return true;\n  });\n\n  const dueToday = withinCampDates.filter((ce) => isDueOnDate(ce, today));\n\n  const logsToday = await prisma.exerciseLog.findMany({\n    where: { userId: req.userId, date: today },\n  });\n  const logByExercise = new Map(logsToday.map((l) => [`${l.campId}:${l.exerciseId}`, l]));\n\n  // Pour les exercices en mode "MAX", on va chercher le record personnel precedent a titre de reference\n  const maxExercises = dueToday.filter((ce) => ce.targetMode === "MAX");\n  const bestByExercise = new Map<string, number>();\n  for (const ce of maxExercises) {\n    const best = await prisma.exerciseLog.findFirst({\n      where: { userId: req.userId, campId: ce.campId, exerciseId: ce.exerciseId },\n      orderBy: { valueDone: "desc" },\n    });\n    if (best) bestByExercise.set(`${ce.campId}:${ce.exerciseId}`, best.valueDone);\n  }\n\n  const result = dueToday.map((ce) => {\n    const key = `${ce.campId}:${ce.exerciseId}`;\n    const log = logByExercise.get(key);\n    return {\n      campExerciseId: ce.id,\n      campId: ce.campId,\n      campName: ce.camp.name,\n      exerciseId: ce.exerciseId,\n      exerciseName: ce.exercise.name,\n      description: ce.description,\n      unit: ce.exercise.unit,\n      targetSets: ce.targetSets,\n      targetMode: ce.targetMode,\n      targetValue: ce.targetValue,\n      personalBest: bestByExercise.get(key) ?? null,\n      done: !!log,\n      log: log ? { setsDone: log.setsDone, valueDone: log.valueDone } : null,\n    };\n  });\n\n  res.json({ date: today.toISOString().slice(0, 10), items: result });\n});\n\nexport default router;\n'
FILES['backend/src/routes/progress.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { computeStreak, isDueOnDate, toDayStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Historique + serie de regularite (streak) pour un exercice donne dans un camp.\n// La consigne (recurrence, objectif) est celle definie par le createur du camp ;\n// l\'historique et le streak restent propres a chaque utilisateur.\nrouter.get("/exercise", async (req: AuthRequest, res) => {\n  const campId = req.query.campId as string;\n  const exerciseId = req.query.exerciseId as string;\n  if (!campId || !exerciseId) {\n    return res.status(400).json({ error: "campId et exerciseId sont requis." });\n  }\n\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const campExercise = await prisma.campExercise.findUnique({\n    where: { campId_exerciseId: { campId, exerciseId } },\n  });\n  if (!campExercise) return res.status(404).json({ error: "Cet exercice ne fait pas partie du camp." });\n\n  const logs = await prisma.exerciseLog.findMany({\n    where: { userId: req.userId, campId, exerciseId },\n    orderBy: { date: "asc" },\n  });\n\n  const completedDates = new Set(logs.map((l) => l.date.toISOString().slice(0, 10)));\n  const streak = computeStreak(campExercise, completedDates, new Date());\n\n  // Taux de regularite depuis le debut de la consigne : jours dus vs jours reussis\n  const today = toDayStart(new Date());\n  let dueCount = 0;\n  let doneCount = 0;\n  const cursor = toDayStart(campExercise.startDate);\n  while (cursor.getTime() <= today.getTime()) {\n    if (isDueOnDate(campExercise, cursor)) {\n      dueCount++;\n      if (completedDates.has(cursor.toISOString().slice(0, 10))) doneCount++;\n    }\n    cursor.setUTCDate(cursor.getUTCDate() + 1);\n  }\n  const regularityRate = dueCount > 0 ? Math.round((doneCount / dueCount) * 100) : 0;\n\n  res.json({\n    program: campExercise,\n    history: logs.map((l) => ({\n      date: l.date.toISOString().slice(0, 10),\n      setsDone: l.setsDone,\n      valueDone: l.valueDone,\n    })),\n    streak,\n    dueCount,\n    doneCount,\n    regularityRate,\n  });\n});\n\nexport default router;\n'
FILES['backend/src/routes/campMessages.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nasync function assertMember(userId: string, campId: string) {\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId, campId } },\n  });\n  return !!membership;\n}\n\n// Liste les messages du camp (les plus recents en dernier), reserve aux membres du camp\nrouter.get("/:campId/messages", async (req: AuthRequest, res) => {\n  const { campId } = req.params;\n  if (!(await assertMember(req.userId!, campId))) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const messages = await prisma.campMessage.findMany({\n    where: { campId },\n    include: { user: { select: { id: true, name: true } } },\n    orderBy: { createdAt: "asc" },\n    take: 200, // garde-fou simple : les 200 derniers messages\n  });\n\n  res.json(messages);\n});\n\nconst sendSchema = z.object({ body: z.string().min(1).max(2000) });\n\n// Envoie un message dans le camp, reserve aux membres du camp\nrouter.post("/:campId/messages", async (req: AuthRequest, res) => {\n  const { campId } = req.params;\n  if (!(await assertMember(req.userId!, campId))) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const parsed = sendSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Le message ne peut pas etre vide." });\n  }\n\n  const message = await prisma.campMessage.create({\n    data: { campId, userId: req.userId!, body: parsed.data.body.trim() },\n    include: { user: { select: { id: true, name: true } } },\n  });\n\n  res.status(201).json(message);\n});\n\nexport default router;\n'
FILES['backend/src/routes/messages.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Renvoie la liste des personnes avec qui on peut discuter : celles qui partagent\n// au moins un camp avec l\'utilisateur (on ne permet pas d\'ecrire a un inconnu).\nrouter.get("/contacts", async (req: AuthRequest, res) => {\n  const myMemberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    select: { campId: true },\n  });\n  const campIds = myMemberships.map((m) => m.campId);\n\n  if (campIds.length === 0) return res.json([]);\n\n  const otherMemberships = await prisma.campMembership.findMany({\n    where: { campId: { in: campIds }, userId: { not: req.userId } },\n    include: { user: { select: { id: true, name: true } } },\n  });\n\n  const contactsById = new Map(otherMemberships.map((m) => [m.user.id, m.user]));\n  res.json([...contactsById.values()]);\n});\n\nasync function assertContact(userId: string, otherUserId: string): Promise<boolean> {\n  const shared = await prisma.campMembership.findFirst({\n    where: {\n      userId: otherUserId,\n      camp: { members: { some: { userId } } },\n    },\n  });\n  return !!shared;\n}\n\n// Recupere la conversation avec un utilisateur donne (dans les deux sens)\nrouter.get("/:userId", async (req: AuthRequest, res) => {\n  const otherUserId = req.params.userId;\n  if (!(await assertContact(req.userId!, otherUserId))) {\n    return res.status(403).json({ error: "Vous ne partagez aucun camp ensemble." });\n  }\n\n  const messages = await prisma.directMessage.findMany({\n    where: {\n      OR: [\n        { senderId: req.userId, recipientId: otherUserId },\n        { senderId: otherUserId, recipientId: req.userId },\n      ],\n    },\n    orderBy: { createdAt: "asc" },\n    take: 300,\n  });\n\n  res.json(messages);\n});\n\nconst sendSchema = z.object({ recipientId: z.string(), body: z.string().min(1).max(2000) });\n\n// Envoie un message prive, uniquement possible si les deux utilisateurs partagent un camp\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = sendSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Message invalide." });\n  }\n  const { recipientId, body } = parsed.data;\n\n  if (recipientId === req.userId) {\n    return res.status(400).json({ error: "Impossible de s\'envoyer un message a soi-meme." });\n  }\n  if (!(await assertContact(req.userId!, recipientId))) {\n    return res.status(403).json({ error: "Vous ne partagez aucun camp ensemble." });\n  }\n\n  const message = await prisma.directMessage.create({\n    data: { senderId: req.userId!, recipientId, body: body.trim() },\n  });\n\n  res.status(201).json(message);\n});\n\nexport default router;\n'
FILES['backend/src/services/notifications.ts'] = 'import cron from "node-cron";\nimport webpush from "web-push";\nimport { prisma } from "../lib/prisma";\nimport { isDueOnDate, toDayStart } from "../utils/recurrence";\n\n// Configure web-push avec les cles VAPID (a generer avec `npm run vapid:generate`)\nexport function initPush() {\n  const publicKey = process.env.VAPID_PUBLIC_KEY;\n  const privateKey = process.env.VAPID_PRIVATE_KEY;\n  const subject = process.env.VAPID_SUBJECT || "mailto:contact@example.com";\n\n  if (!publicKey || !privateKey) {\n    console.warn(\n      "[push] Cles VAPID manquantes : les notifications push sont desactivees. " +\n        "Genere-les avec `npm run vapid:generate` et renseigne .env"\n    );\n    return;\n  }\n  webpush.setVapidDetails(subject, publicKey, privateKey);\n  console.log("[push] Notifications push configurees.");\n}\n\n// Verifie, pour chaque utilisateur, les exercices dus aujourd\'hui (selon la consigne du camp)\n// et pas encore faits, puis envoie une notification de rappel groupee.\nexport async function sendDailyReminders() {\n  const today = toDayStart(new Date());\n\n  const memberships = await prisma.campMembership.findMany({\n    include: {\n      user: { include: { subscriptions: true } },\n      camp: { include: { exercises: { include: { exercise: true } } } },\n    },\n  });\n\n  const dueByUser = new Map<string, { name: string }[]>();\n\n  for (const membership of memberships) {\n    const { camp, userId } = membership;\n    if (camp.startDate && today.getTime() < toDayStart(camp.startDate).getTime()) continue;\n    if (camp.endDate && today.getTime() > toDayStart(camp.endDate).getTime()) continue;\n\n    for (const ce of camp.exercises) {\n      if (!isDueOnDate(ce, today)) continue;\n\n      const alreadyLogged = await prisma.exerciseLog.findUnique({\n        where: {\n          userId_campId_exerciseId_date: {\n            userId,\n            campId: ce.campId,\n            exerciseId: ce.exerciseId,\n            date: today,\n          },\n        },\n      });\n      if (alreadyLogged) continue;\n\n      const list = dueByUser.get(userId) || [];\n      list.push({ name: ce.exercise.name });\n      dueByUser.set(userId, list);\n    }\n  }\n\n  const subscriptionsByUser = new Map(memberships.map((m) => [m.userId, m.user.subscriptions]));\n\n  for (const [userId, pending] of dueByUser) {\n    if (pending.length === 0) continue;\n    const subscriptions = subscriptionsByUser.get(userId) ?? [];\n    if (subscriptions.length === 0) continue;\n\n    const names = [...new Set(pending.map((p) => p.name))];\n    const payload = JSON.stringify({\n      title: "C\'est le moment de faire votre seance ! 💪",\n      body:\n        names.length === 1\n          ? `${names[0]} t\'attend aujourd\'hui.`\n          : `${names.slice(0, 3).join(", ")}${names.length > 3 ? "…" : ""} t\'attendent aujourd\'hui.`,\n    });\n\n    for (const sub of subscriptions) {\n      try {\n        await webpush.sendNotification(\n          { endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } },\n          payload\n        );\n      } catch (err: any) {\n        // Abonnement expire ou invalide : on le retire\n        if (err.statusCode === 404 || err.statusCode === 410) {\n          await prisma.pushSubscription.delete({ where: { id: sub.id } }).catch(() => {});\n        } else {\n          console.error("[push] Erreur d\'envoi :", err.message);\n        }\n      }\n    }\n  }\n}\n\n// Planifie l\'envoi quotidien a l\'heure configuree (REMINDER_HOUR, defaut 18h, heure serveur)\nexport function scheduleReminders() {\n  const hour = Number(process.env.REMINDER_HOUR ?? 18);\n  const cronExpr = `0 ${hour} * * *`;\n  cron.schedule(cronExpr, () => {\n    sendDailyReminders().catch((err) => console.error("[push] Erreur lors de l\'envoi des rappels :", err));\n  });\n  console.log(`[push] Rappels quotidiens planifies a ${hour}h (heure serveur).`);\n}\n'
FILES['frontend/src/lib/duration.ts'] = '// Convertit un nombre total de secondes en affichage "mm:ss"\nexport function secondsToMMSS(totalSeconds: number): string {\n  const m = Math.floor(totalSeconds / 60);\n  const s = totalSeconds % 60;\n  return `${m}:${s.toString().padStart(2, "0")}`;\n}\n\n// Convertit minutes + secondes en un total de secondes\nexport function mmssToSeconds(minutes: number, seconds: number): number {\n  return Math.max(0, minutes) * 60 + Math.max(0, Math.min(59, seconds));\n}\n\n// Decompose un total de secondes en {minutes, seconds}, pratique pour prefiller deux champs\nexport function splitSeconds(totalSeconds: number): { minutes: number; seconds: number } {\n  return { minutes: Math.floor(totalSeconds / 60), seconds: totalSeconds % 60 };\n}\n'
FILES['frontend/src/components/DurationInput.tsx'] = 'import { splitSeconds, mmssToSeconds } from "../lib/duration";\n\ninterface Props {\n  totalSeconds: number;\n  onChange: (totalSeconds: number) => void;\n  className?: string;\n}\n\n// Champ de saisie d\'une duree au format min:sec (plus naturel que des secondes brutes\n// pour des exercices comme le gainage ou la chaise contre le mur).\nexport default function DurationInput({ totalSeconds, onChange, className }: Props) {\n  const { minutes, seconds } = splitSeconds(totalSeconds);\n\n  return (\n    <div className={`flex items-center gap-1 ${className ?? ""}`}>\n      <input\n        type="number"\n        min={0}\n        value={minutes}\n        onChange={(e) => onChange(mmssToSeconds(Number(e.target.value), seconds))}\n        className="w-14 bg-surface border border-border rounded-md px-2 py-1.5 text-sm text-center"\n        aria-label="Minutes"\n      />\n      <span className="text-muted text-sm">min</span>\n      <input\n        type="number"\n        min={0}\n        max={59}\n        value={seconds}\n        onChange={(e) => onChange(mmssToSeconds(minutes, Number(e.target.value)))}\n        className="w-14 bg-surface border border-border rounded-md px-2 py-1.5 text-sm text-center"\n        aria-label="Secondes"\n      />\n      <span className="text-muted text-sm">sec</span>\n    </div>\n  );\n}\n'
FILES['frontend/src/components/ProgramForm.tsx'] = 'import { useState } from "react";\nimport { api, ApiError } from "../api/client";\nimport DurationInput from "./DurationInput";\n\n// "Program" designe ici la consigne d\'un exercice au sein d\'un camp (CampExercise cote API).\n// Seul le createur du camp (la "casquette entraineur") peut la modifier ; les autres membres\n// ne font que la consulter (voir CampDetail.tsx).\nexport interface Program {\n  id: string;\n  exerciseId: string;\n  description: string | null;\n  targetSets: number;\n  targetMode: "FIXED" | "MAX";\n  targetValue: number | null;\n  recurrenceType: "DAILY" | "WEEKLY" | "EVERY_N_DAYS";\n  daysOfWeek: string | null;\n  intervalDays: number | null;\n}\n\ninterface Props {\n  campId: string;\n  exerciseId: string;\n  exerciseName: string;\n  unit: "REPS" | "SECONDS";\n  existing?: Program;\n  onSaved: () => void;\n  onCancel: () => void;\n}\n\nconst WEEKDAYS = [\n  { value: 1, label: "Lun" },\n  { value: 2, label: "Mar" },\n  { value: 3, label: "Mer" },\n  { value: 4, label: "Jeu" },\n  { value: 5, label: "Ven" },\n  { value: 6, label: "Sam" },\n  { value: 0, label: "Dim" },\n];\n\nexport default function ProgramForm({ campId, exerciseId, exerciseName, unit, existing, onSaved, onCancel }: Props) {\n  const [description, setDescription] = useState(existing?.description ?? "");\n  const [targetSets, setTargetSets] = useState(existing?.targetSets ?? 3);\n  const [targetMode, setTargetMode] = useState<"FIXED" | "MAX">(existing?.targetMode ?? "FIXED");\n  const [targetValue, setTargetValue] = useState(existing?.targetValue ?? (unit === "REPS" ? 10 : 30));\n  const [recurrenceType, setRecurrenceType] = useState<"DAILY" | "WEEKLY" | "EVERY_N_DAYS">(\n    existing?.recurrenceType ?? "DAILY"\n  );\n  const [daysOfWeek, setDaysOfWeek] = useState<number[]>(\n    existing?.daysOfWeek ? JSON.parse(existing.daysOfWeek) : [1, 3, 5]\n  );\n  const [intervalDays, setIntervalDays] = useState(existing?.intervalDays ?? 2);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  function toggleDay(day: number) {\n    setDaysOfWeek((prev) => (prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day].sort()));\n  }\n\n  async function save() {\n    setError(null);\n    if (recurrenceType === "WEEKLY" && daysOfWeek.length === 0) {\n      setError("Choisis au moins un jour de la semaine.");\n      return;\n    }\n    setBusy(true);\n    try {\n      const payload: Record<string, unknown> = {\n        campId,\n        exerciseId,\n        description: description.trim() || null,\n        targetSets,\n        targetMode,\n        recurrenceType,\n      };\n      if (targetMode === "FIXED") payload.targetValue = targetValue;\n      if (recurrenceType === "WEEKLY") payload.daysOfWeek = daysOfWeek;\n      if (recurrenceType === "EVERY_N_DAYS") payload.intervalDays = intervalDays;\n\n      await api.put("/camp-exercises", payload);\n      onSaved();\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible d\'enregistrer cette consigne.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  const unitLabel = unit === "REPS" ? "repetitions" : "duree";\n\n  return (\n    <div className="bg-surface2 border border-border rounded-lg p-4 space-y-4">\n      <h3 className="font-display uppercase tracking-wide text-sm">{exerciseName}</h3>\n\n      <div>\n        <label className="block text-xs text-muted mb-1">Consigne (visible par tous les membres)</label>\n        <textarea\n          value={description}\n          onChange={(e) => setDescription(e.target.value)}\n          placeholder="Ex : Dos bien droit, descendre lentement..."\n          rows={2}\n          className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm resize-none"\n        />\n      </div>\n\n      <div>\n        <label className="block text-xs text-muted mb-1">Type d\'objectif</label>\n        <div className="flex gap-1.5 mb-3">\n          <button\n            type="button"\n            onClick={() => setTargetMode("FIXED")}\n            className={`px-3 py-1.5 rounded text-xs border ${\n              targetMode === "FIXED" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n            }`}\n          >\n            Objectif chiffre\n          </button>\n          <button\n            type="button"\n            onClick={() => setTargetMode("MAX")}\n            className={`px-3 py-1.5 rounded text-xs border ${\n              targetMode === "MAX" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n            }`}\n          >\n            A fond (record perso)\n          </button>\n        </div>\n      </div>\n\n      <div className="grid grid-cols-2 gap-3">\n        <div>\n          <label className="block text-xs text-muted mb-1">Nombre de series</label>\n          <input\n            type="number"\n            min={1}\n            value={targetSets}\n            onChange={(e) => setTargetSets(Number(e.target.value))}\n            className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm"\n          />\n        </div>\n        {targetMode === "FIXED" ? (\n          <div>\n            <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n            {unit === "SECONDS" ? (\n              <DurationInput totalSeconds={targetValue} onChange={setTargetValue} />\n            ) : (\n              <input\n                type="number"\n                min={1}\n                value={targetValue}\n                onChange={(e) => setTargetValue(Number(e.target.value))}\n                className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm"\n              />\n            )}\n          </div>\n        ) : (\n          <div>\n            <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n            <div className="w-full bg-surface border border-dashed border-border rounded-md px-2 py-1.5 text-sm text-muted">\n              A fond, sans limite fixee\n            </div>\n          </div>\n        )}\n      </div>\n\n      <div>\n        <label className="block text-xs text-muted mb-1">Frequence</label>\n        <select\n          value={recurrenceType}\n          onChange={(e) => setRecurrenceType(e.target.value as any)}\n          className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm mb-2"\n        >\n          <option value="DAILY">Tous les jours</option>\n          <option value="WEEKLY">Certains jours de la semaine</option>\n          <option value="EVERY_N_DAYS">Tous les X jours</option>\n        </select>\n\n        {recurrenceType === "WEEKLY" && (\n          <div className="flex flex-wrap gap-1.5">\n            {WEEKDAYS.map((d) => (\n              <button\n                type="button"\n                key={d.value}\n                onClick={() => toggleDay(d.value)}\n                className={`px-2.5 py-1 rounded text-xs border ${\n                  daysOfWeek.includes(d.value)\n                    ? "bg-accent/20 border-accent text-text"\n                    : "bg-surface border-border text-muted"\n                }`}\n              >\n                {d.label}\n              </button>\n            ))}\n          </div>\n        )}\n\n        {recurrenceType === "EVERY_N_DAYS" && (\n          <div className="flex items-center gap-2 text-sm">\n            <span className="text-muted">Tous les</span>\n            <input\n              type="number"\n              min={1}\n              value={intervalDays}\n              onChange={(e) => setIntervalDays(Number(e.target.value))}\n              className="w-16 bg-surface border border-border rounded-md px-2 py-1"\n            />\n            <span className="text-muted">jours</span>\n          </div>\n        )}\n      </div>\n\n      {error && <p className="text-sm text-accent">{error}</p>}\n\n      <div className="flex gap-2">\n        <button\n          onClick={save}\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-1.5 text-sm disabled:opacity-60"\n        >\n          {busy ? "Enregistrement..." : "Enregistrer"}\n        </button>\n        <button onClick={onCancel} className="text-muted hover:text-text text-sm px-2">\n          Annuler\n        </button>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CampDetail.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useParams } from "react-router-dom";\nimport { api } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\nimport ProgramForm, { Program } from "../components/ProgramForm";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface CampExerciseData extends Program {\n  exercise: { id: string; name: string; unit: "REPS" | "SECONDS"; description: string | null };\n}\n\ninterface CampDetailData {\n  id: string;\n  name: string;\n  code: string;\n  createdById: string;\n  startDate: string | null;\n  endDate: string | null;\n  exercises: CampExerciseData[];\n  members: { user: { id: string; name: string } }[];\n}\n\nconst RECURRENCE_LABEL: Record<string, (p: Program) => string> = {\n  DAILY: () => "Tous les jours",\n  WEEKLY: (p) => {\n    const days = p.daysOfWeek ? (JSON.parse(p.daysOfWeek) as number[]) : [];\n    const names = ["Dim", "Lun", "Mar", "Mer", "Jeu", "Ven", "Sam"];\n    return days.map((d) => names[d]).join(", ");\n  },\n  EVERY_N_DAYS: (p) => `Tous les ${p.intervalDays} jours`,\n};\n\nexport default function CampDetail() {\n  const { id } = useParams<{ id: string }>();\n  const { user } = useAuth();\n  const [camp, setCamp] = useState<CampDetailData | null>(null);\n  const [editingExerciseId, setEditingExerciseId] = useState<string | null>(null);\n\n  function load() {\n    if (!id) return;\n    api.get<CampDetailData>(`/camps/${id}`).then(setCamp);\n  }\n  useEffect(load, [id]);\n\n  if (!camp) return <p className="text-muted">Chargement...</p>;\n\n  const isCoach = user?.id === camp.createdById;\n\n  return (\n    <div className="max-w-2xl">\n      <div className="flex items-start justify-between flex-wrap gap-3 mb-2">\n        <div>\n          <h1 className="font-display text-3xl uppercase tracking-wide">{camp.name}</h1>\n          <p className="text-muted text-sm">\n            {camp.members.length} membre{camp.members.length > 1 ? "s" : ""} :{" "}\n            {camp.members.map((m) => m.user.name).join(", ")}\n          </p>\n          {(camp.startDate || camp.endDate) && (\n            <p className="text-muted text-xs mt-1">\n              {camp.startDate ? `Du ${new Date(camp.startDate).toLocaleDateString("fr-FR")}` : "Sans date de debut"}\n              {camp.endDate ? ` au ${new Date(camp.endDate).toLocaleDateString("fr-FR")}` : ""}\n            </p>\n          )}\n        </div>\n        <div className="bg-surface border border-border rounded-md px-3 py-2 text-center">\n          <p className="text-[10px] uppercase tracking-widest text-muted">Code</p>\n          <p className="font-mono text-lg text-accent">{camp.code}</p>\n        </div>\n      </div>\n\n      <Link\n        to={`/camps/${camp.id}/discussion`}\n        className="inline-block mt-2 text-sm text-accent hover:text-accentSoft"\n      >\n        💬 Discussion du camp\n      </Link>\n\n      <h2 className="font-display uppercase tracking-wide text-lg mt-8 mb-1">Exercices du camp</h2>\n      <p className="text-muted text-sm mb-4">\n        {isCoach\n          ? "En tant que createur du camp, tu definis la consigne (objectif, frequence) suivie par tous les membres."\n          : "Consignes definies par le createur du camp."}\n      </p>\n\n      <div className="space-y-3">\n        {camp.exercises.map((ce) => {\n          const isEditing = editingExerciseId === ce.exercise.id;\n\n          if (isEditing) {\n            return (\n              <ProgramForm\n                key={ce.exercise.id}\n                campId={camp.id}\n                exerciseId={ce.exercise.id}\n                exerciseName={ce.exercise.name}\n                unit={ce.exercise.unit}\n                existing={ce}\n                onSaved={() => {\n                  setEditingExerciseId(null);\n                  load();\n                }}\n                onCancel={() => setEditingExerciseId(null)}\n              />\n            );\n          }\n\n          const unitLabel = ce.exercise.unit === "REPS" ? "reps" : "";\n          const valueLabel =\n            ce.exercise.unit === "SECONDS" && ce.targetValue != null\n              ? secondsToMMSS(ce.targetValue)\n              : `${ce.targetValue} ${unitLabel}`;\n\n          return (\n            <div key={ce.exercise.id} className="bg-surface border border-border rounded-lg p-4">\n              <div className="flex items-center justify-between flex-wrap gap-3">\n                <div>\n                  <p className="font-medium">{ce.exercise.name}</p>\n                  <p className="text-sm text-muted">\n                    {ce.targetMode === "MAX"\n                      ? `${ce.targetSets} serie${ce.targetSets > 1 ? "s" : ""} a fond`\n                      : `${ce.targetSets} x ${valueLabel}`}{" "}\n                    · {RECURRENCE_LABEL[ce.recurrenceType](ce)}\n                  </p>\n                  {ce.description && <p className="text-xs text-muted mt-1 italic">"{ce.description}"</p>}\n                </div>\n                <div className="flex gap-3 items-center shrink-0">\n                  <Link\n                    to={`/camps/${camp.id}/progression/${ce.exercise.id}`}\n                    className="text-sm text-accent hover:text-accentSoft"\n                  >\n                    Progression\n                  </Link>\n                  {isCoach && (\n                    <button\n                      onClick={() => setEditingExerciseId(ce.exercise.id)}\n                      className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                    >\n                      Modifier\n                    </button>\n                  )}\n                </div>\n              </div>\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Today.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api } from "../api/client";\nimport DurationInput from "../components/DurationInput";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface TodayItem {\n  campExerciseId: string;\n  campId: string;\n  campName: string;\n  exerciseId: string;\n  exerciseName: string;\n  description: string | null;\n  unit: "REPS" | "SECONDS";\n  targetSets: number;\n  targetMode: "FIXED" | "MAX";\n  targetValue: number | null;\n  personalBest: number | null;\n  done: boolean;\n  log: { setsDone: number; valueDone: number } | null;\n}\n\ninterface NewBadge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\nexport default function Today() {\n  const [items, setItems] = useState<TodayItem[] | null>(null);\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [sets, setSets] = useState(0);\n  const [value, setValue] = useState(0);\n  const [celebrating, setCelebrating] = useState<NewBadge[]>([]);\n\n  function load() {\n    api.get<{ date: string; items: TodayItem[] }>("/today").then((res) => setItems(res.items));\n  }\n  useEffect(load, []);\n\n  function startEditing(item: TodayItem) {\n    setEditingId(item.campExerciseId);\n    setSets(item.log?.setsDone ?? item.targetSets);\n    setValue(item.log?.valueDone ?? item.targetValue ?? item.personalBest ?? 0);\n  }\n\n  async function confirm(item: TodayItem) {\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campId: item.campId,\n      exerciseId: item.exerciseId,\n      setsDone: sets,\n      valueDone: value,\n    });\n    setEditingId(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function undo(item: TodayItem) {\n    await api.del(`/logs?campId=${item.campId}&exerciseId=${item.exerciseId}`);\n    load();\n  }\n\n  const doneCount = items?.filter((i) => i.done).length ?? 0;\n  const total = items?.length ?? 0;\n\n  return (\n    <div className="max-w-xl">\n      {celebrating.length > 0 && (\n        <div className="bg-accent/10 border border-accent rounded-xl p-4 mb-5">\n          {celebrating.map((b) => (\n            <p key={b.key} className="text-sm">\n              <span className="text-xl mr-2">{b.emoji}</span>\n              Nouveau badge : <span className="font-semibold">{b.name}</span> — {b.description}\n            </p>\n          ))}\n          <button onClick={() => setCelebrating([])} className="text-xs text-muted hover:text-text mt-2">\n            Fermer\n          </button>\n        </div>\n      )}\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Aujourd\'hui</h1>\n      <p className="text-muted text-sm mb-6">\n        {total === 0\n          ? "Rien de prevu aujourd\'hui."\n          : `${doneCount} / ${total} seance${total > 1 ? "s" : ""} validee${doneCount > 1 ? "s" : ""}.`}\n      </p>\n\n      {items === null && <p className="text-muted">Chargement...</p>}\n\n      {items?.length === 0 && (\n        <div className="bg-surface border border-dashed border-border rounded-xl p-8 text-center">\n          <p className="text-muted text-sm mb-3">\n            Aucun exercice programme pour aujourd\'hui. Va voir tes camps pour rejoindre ou creer un camp.\n          </p>\n          <Link to="/camps" className="text-accent hover:text-accentSoft text-sm">\n            Voir mes camps\n          </Link>\n        </div>\n      )}\n\n      <div className="space-y-3">\n        {items?.map((item) => {\n          const unitLabel = item.unit === "REPS" ? "reps" : "sec";\n          const isEditing = editingId === item.campExerciseId;\n          const targetLabel =\n            item.targetMode === "MAX"\n              ? `${item.targetSets} serie${item.targetSets > 1 ? "s" : ""} a fond${\n                  item.personalBest\n                    ? ` (record : ${item.unit === "SECONDS" ? secondsToMMSS(item.personalBest) : item.personalBest} ${unitLabel})`\n                    : ""\n                }`\n              : `${item.targetSets} x ${item.unit === "SECONDS" && item.targetValue ? secondsToMMSS(item.targetValue) : item.targetValue} ${item.unit === "SECONDS" ? "" : unitLabel}`;\n\n          return (\n            <div\n              key={item.campExerciseId}\n              className={`bg-surface border rounded-xl p-4 transition-colors ${\n                item.done ? "border-success/50" : "border-border"\n              }`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <p className="font-medium">{item.exerciseName}</p>\n                  <p className="text-xs text-muted">\n                    {item.campName} · objectif {targetLabel}\n                  </p>\n                  {item.description && <p className="text-xs text-muted italic mt-0.5">"{item.description}"</p>}\n                </div>\n\n                {!isEditing && (\n                  <button\n                    onClick={() => (item.done ? undo(item) : startEditing(item))}\n                    className={`stamp-btn w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold border-2 ${\n                      item.done\n                        ? "bg-success/20 border-success text-success"\n                        : "bg-surface2 border-border text-muted hover:border-accent hover:text-accent"\n                    }`}\n                    aria-label={item.done ? "Annuler la validation" : "Valider la seance"}\n                    title={item.done ? "Fait - clique pour annuler" : "Marquer comme fait"}\n                  >\n                    {item.done ? "✓" : ""}\n                  </button>\n                )}\n              </div>\n\n              {item.done && item.log && (\n                <p className="text-xs text-muted mt-2">\n                  Realise : {item.log.setsDone} x{" "}\n                  {item.unit === "SECONDS" ? secondsToMMSS(item.log.valueDone) : `${item.log.valueDone} ${unitLabel}`}\n                </p>\n              )}\n\n              {isEditing && (\n                <div className="mt-3 flex items-end gap-3 flex-wrap bg-surface2 border border-border rounded-md p-3">\n                  <div>\n                    <label className="block text-xs text-muted mb-1">Series faites</label>\n                    <input\n                      type="number"\n                      min={0}\n                      value={sets}\n                      onChange={(e) => setSets(Number(e.target.value))}\n                      className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                    />\n                  </div>\n                  <div>\n                    <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n                    {item.unit === "SECONDS" ? (\n                      <DurationInput totalSeconds={value} onChange={setValue} />\n                    ) : (\n                      <input\n                        type="number"\n                        min={0}\n                        value={value}\n                        onChange={(e) => setValue(Number(e.target.value))}\n                        className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                      />\n                    )}\n                  </div>\n                  <button\n                    onClick={() => confirm(item)}\n                    className="bg-accent text-bg font-semibold rounded-md px-4 py-1.5 text-sm"\n                  >\n                    Valider\n                  </button>\n                  <button onClick={() => setEditingId(null)} className="text-muted text-sm px-2">\n                    Annuler\n                  </button>\n                </div>\n              )}\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Progress.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useParams } from "react-router-dom";\nimport { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";\nimport { api } from "../api/client";\nimport StampGrid from "../components/StampGrid";\nimport { computeDueDates } from "../lib/recurrence";\nimport { secondsToMMSS } from "../lib/duration";\nimport type { Program } from "../components/ProgramForm";\n\ninterface ProgressData {\n  program: Program & { startDate: string };\n  history: { date: string; setsDone: number; valueDone: number }[];\n  streak: number;\n  dueCount: number;\n  doneCount: number;\n  regularityRate: number;\n}\n\nexport default function Progress() {\n  const { id: campId, exerciseId } = useParams<{ id: string; exerciseId: string }>();\n  const [data, setData] = useState<ProgressData | null>(null);\n  const [exerciseName, setExerciseName] = useState("");\n  const [unit, setUnit] = useState<"REPS" | "SECONDS">("REPS");\n\n  useEffect(() => {\n    if (!campId || !exerciseId) return;\n    api\n      .get<ProgressData>(`/progress/exercise?campId=${campId}&exerciseId=${exerciseId}`)\n      .then(setData);\n    api.get<{ exercises: { exercise: { id: string; name: string; unit: "REPS" | "SECONDS" } }[] }>(\n      `/camps/${campId}`\n    ).then((camp) => {\n      const exo = camp.exercises.find((e) => e.exercise.id === exerciseId)?.exercise;\n      if (exo) {\n        setExerciseName(exo.name);\n        setUnit(exo.unit);\n      }\n    });\n  }, [campId, exerciseId]);\n\n  if (!data) return <p className="text-muted">Chargement...</p>;\n\n  const completedDates = new Set(data.history.map((h) => h.date));\n  const dueDates = computeDueDates(data.program, 84);\n  const unitLabel = unit === "REPS" ? "repetitions" : "secondes";\n\n  return (\n    <div className="max-w-2xl">\n      <Link to={`/camps/${campId}`} className="text-sm text-muted hover:text-accent">\n        ← Retour au camp\n      </Link>\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mt-2 mb-1">{exerciseName}</h1>\n      <p className="text-muted text-sm mb-6">Ta progression et ta regularite, pas de classement, juste toi.</p>\n\n      <div className="grid grid-cols-3 gap-3 mb-6">\n        <div className="bg-surface border border-border rounded-xl p-4 text-center">\n          <p className="font-display text-3xl text-accent">{data.streak}</p>\n          <p className="text-xs text-muted uppercase tracking-wide mt-1">Jours d\'affilee</p>\n        </div>\n        <div className="bg-surface border border-border rounded-xl p-4 text-center">\n          <p className="font-display text-3xl text-success">{data.regularityRate}%</p>\n          <p className="text-xs text-muted uppercase tracking-wide mt-1">Regularite</p>\n        </div>\n        <div className="bg-surface border border-border rounded-xl p-4 text-center">\n          <p className="font-display text-3xl">\n            {data.doneCount}/{data.dueCount}\n          </p>\n          <p className="text-xs text-muted uppercase tracking-wide mt-1">Seances faites</p>\n        </div>\n      </div>\n\n      <div className="bg-surface border border-border rounded-xl p-5 mb-6">\n        <h2 className="font-display uppercase tracking-wide text-sm mb-3">Carte de pointage (12 dernieres semaines)</h2>\n        <StampGrid completedDates={completedDates} dueDates={dueDates} days={84} />\n        <div className="flex gap-4 mt-3 text-xs text-muted">\n          <span className="flex items-center gap-1">\n            <span className="w-2.5 h-2.5 rounded-sm inline-block stamp-cell done" /> Fait\n          </span>\n          <span className="flex items-center gap-1">\n            <span className="w-2.5 h-2.5 rounded-sm inline-block stamp-cell missed" /> Manque\n          </span>\n          <span className="flex items-center gap-1">\n            <span className="w-2.5 h-2.5 rounded-sm inline-block stamp-cell future" /> Non prevu\n          </span>\n        </div>\n      </div>\n\n      <div className="bg-surface border border-border rounded-xl p-5">\n        <h2 className="font-display uppercase tracking-wide text-sm mb-3">\n          Evolution ({unitLabel} par serie realisees)\n        </h2>\n        {data.history.length === 0 ? (\n          <p className="text-muted text-sm">Pas encore de donnees, valide ta premiere seance dans "Aujourd\'hui".</p>\n        ) : (\n          <div style={{ width: "100%", height: 260 }}>\n            <ResponsiveContainer>\n              <LineChart data={data.history}>\n                <CartesianGrid stroke="#2E323A" strokeDasharray="3 3" />\n                <XAxis dataKey="date" stroke="#8B909A" tick={{ fontSize: 11 }} />\n                <YAxis\n                  stroke="#8B909A"\n                  tick={{ fontSize: 11 }}\n                  tickFormatter={(v: number) => (unit === "SECONDS" ? secondsToMMSS(v) : String(v))}\n                />\n                <Tooltip\n                  contentStyle={{ backgroundColor: "#1D2025", border: "1px solid #2E323A", fontSize: 12 }}\n                  labelStyle={{ color: "#F4F2EC" }}\n                  formatter={(v: number) => (unit === "SECONDS" ? secondsToMMSS(v) : v)}\n                />\n                <Line type="monotone" dataKey="valueDone" stroke="#FF4B2E" strokeWidth={2} dot={{ r: 3 }} />\n              </LineChart>\n            </ResponsiveContainer>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CreateCamp.tsx'] = 'import { FormEvent, useState } from "react";\nimport { useNavigate } from "react-router-dom";\nimport { api, ApiError } from "../api/client";\nimport ExercisePicker from "../components/ExercisePicker";\n\nexport default function CreateCamp() {\n  const navigate = useNavigate();\n  const [name, setName] = useState("");\n  const [selected, setSelected] = useState<string[]>([]);\n  const [startDate, setStartDate] = useState("");\n  const [endDate, setEndDate] = useState("");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [createdCode, setCreatedCode] = useState<string | null>(null);\n  const [createdId, setCreatedId] = useState<string | null>(null);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    if (selected.length === 0) {\n      setError("Selectionne au moins un exercice.");\n      return;\n    }\n    if (startDate && endDate && endDate < startDate) {\n      setError("La date de fin doit etre apres la date de debut.");\n      return;\n    }\n    setBusy(true);\n    try {\n      const camp = await api.post<{ id: string; code: string }>("/camps", {\n        name,\n        exerciseIds: selected,\n        startDate: startDate || null,\n        endDate: endDate || null,\n      });\n      setCreatedCode(camp.code);\n      setCreatedId(camp.id);\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de creer le camp.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  if (createdCode && createdId) {\n    return (\n      <div className="max-w-md">\n        <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Camp cree !</h1>\n        <p className="text-muted text-sm mb-6">\n          Partage ce code pour inviter d\'autres personnes a rejoindre "{name}".\n        </p>\n        <div className="bg-surface border-2 border-dashed border-accent rounded-xl p-6 text-center mb-6">\n          <p className="text-xs uppercase tracking-widest text-muted mb-2">Code d\'invitation</p>\n          <p className="font-mono text-4xl tracking-[0.3em] text-accent">{createdCode}</p>\n        </div>\n        <button\n          onClick={() => navigate(`/camps/${createdId}`)}\n          className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2"\n        >\n          Definir les consignes des exercices\n        </button>\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-xl">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Nouveau camp</h1>\n      <p className="text-muted text-sm mb-6">\n        Choisis un nom et les exercices qui feront partie de ce camp. En tant que createur, tu definiras ensuite\n        la consigne (objectif, frequence) suivie par tous les membres.\n      </p>\n\n      <form onSubmit={onSubmit} className="space-y-5">\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="name">\n            Nom du camp\n          </label>\n          <input\n            id="name"\n            required\n            value={name}\n            onChange={(e) => setName(e.target.value)}\n            placeholder="Ex : Preparation pompiers volontaires"\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-2">Exercices du camp</label>\n          <ExercisePicker selected={selected} onChange={setSelected} />\n        </div>\n\n        <div className="grid grid-cols-2 gap-4">\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="startDate">\n              Date de debut (optionnel)\n            </label>\n            <input\n              id="startDate"\n              type="date"\n              value={startDate}\n              onChange={(e) => setStartDate(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="endDate">\n              Date de fin (optionnel)\n            </label>\n            <input\n              id="endDate"\n              type="date"\n              value={endDate}\n              onChange={(e) => setEndDate(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n        </div>\n\n        {error && <p className="text-sm text-accent">{error}</p>}\n\n        <button\n          type="submit"\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2 disabled:opacity-60"\n        >\n          {busy ? "Creation..." : "Creer le camp"}\n        </button>\n      </form>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CampChat.tsx'] = 'import { FormEvent, useEffect, useRef, useState } from "react";\nimport { Link, useParams } from "react-router-dom";\nimport { api } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\n\ninterface CampMessage {\n  id: string;\n  body: string;\n  createdAt: string;\n  user: { id: string; name: string };\n}\n\nexport default function CampChat() {\n  const { id: campId } = useParams<{ id: string }>();\n  const { user } = useAuth();\n  const [messages, setMessages] = useState<CampMessage[] | null>(null);\n  const [text, setText] = useState("");\n  const [campName, setCampName] = useState("");\n  const bottomRef = useRef<HTMLDivElement>(null);\n\n  function load() {\n    if (!campId) return;\n    api.get<CampMessage[]>(`/camps/${campId}/messages`).then(setMessages);\n  }\n\n  useEffect(() => {\n    if (!campId) return;\n    api.get<{ name: string }>(`/camps/${campId}`).then((c) => setCampName(c.name));\n    load();\n    // Rafraichissement simple par sondage, suffisant pour un usage a deux/quelques personnes\n    const interval = setInterval(load, 5000);\n    return () => clearInterval(interval);\n  }, [campId]);\n\n  useEffect(() => {\n    bottomRef.current?.scrollIntoView({ behavior: "smooth" });\n  }, [messages?.length]);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    if (!text.trim() || !campId) return;\n    await api.post(`/camps/${campId}/messages`, { body: text.trim() });\n    setText("");\n    load();\n  }\n\n  return (\n    <div className="max-w-xl flex flex-col h-[calc(100vh-8rem)] md:h-[calc(100vh-6rem)]">\n      <Link to={`/camps/${campId}`} className="text-sm text-muted hover:text-accent mb-2">\n        ← Retour au camp\n      </Link>\n      <h1 className="font-display text-2xl uppercase tracking-wide mb-4">Discussion · {campName}</h1>\n\n      <div className="flex-1 overflow-y-auto bg-surface border border-border rounded-xl p-4 space-y-3 mb-3">\n        {messages === null && <p className="text-muted text-sm">Chargement...</p>}\n        {messages?.length === 0 && (\n          <p className="text-muted text-sm text-center py-8">Aucun message pour l\'instant, lance la discussion !</p>\n        )}\n        {messages?.map((m) => {\n          const isMine = m.user.id === user?.id;\n          return (\n            <div key={m.id} className={`flex ${isMine ? "justify-end" : "justify-start"}`}>\n              <div className={`max-w-[80%] rounded-lg px-3 py-2 ${isMine ? "bg-accent/20" : "bg-surface2"}`}>\n                {!isMine && <p className="text-[10px] text-muted mb-0.5">{m.user.name}</p>}\n                <p className="text-sm whitespace-pre-wrap break-words">{m.body}</p>\n                <p className="text-[10px] text-muted mt-1">\n                  {new Date(m.createdAt).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}\n                </p>\n              </div>\n            </div>\n          );\n        })}\n        <div ref={bottomRef} />\n      </div>\n\n      <form onSubmit={onSubmit} className="flex gap-2">\n        <input\n          value={text}\n          onChange={(e) => setText(e.target.value)}\n          placeholder="Ecris un message..."\n          className="flex-1 bg-surface2 border border-border rounded-md px-3 py-2 text-sm"\n        />\n        <button\n          type="submit"\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-2 text-sm"\n        >\n          Envoyer\n        </button>\n      </form>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Messages.tsx'] = 'import { FormEvent, useEffect, useRef, useState } from "react";\nimport { api } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\n\ninterface Contact {\n  id: string;\n  name: string;\n}\n\ninterface DirectMessage {\n  id: string;\n  body: string;\n  createdAt: string;\n  senderId: string;\n  recipientId: string;\n}\n\nexport default function Messages() {\n  const { user } = useAuth();\n  const [contacts, setContacts] = useState<Contact[] | null>(null);\n  const [selected, setSelected] = useState<Contact | null>(null);\n  const [messages, setMessages] = useState<DirectMessage[] | null>(null);\n  const [text, setText] = useState("");\n  const bottomRef = useRef<HTMLDivElement>(null);\n\n  useEffect(() => {\n    api.get<Contact[]>("/messages/contacts").then((list) => {\n      setContacts(list);\n      if (list.length > 0 && !selected) setSelected(list[0]);\n    });\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  function loadConversation() {\n    if (!selected) return;\n    api.get<DirectMessage[]>(`/messages/${selected.id}`).then(setMessages);\n  }\n\n  useEffect(() => {\n    if (!selected) return;\n    loadConversation();\n    const interval = setInterval(loadConversation, 5000);\n    return () => clearInterval(interval);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [selected]);\n\n  useEffect(() => {\n    bottomRef.current?.scrollIntoView({ behavior: "smooth" });\n  }, [messages?.length]);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    if (!text.trim() || !selected) return;\n    await api.post("/messages", { recipientId: selected.id, body: text.trim() });\n    setText("");\n    loadConversation();\n  }\n\n  return (\n    <div className="max-w-3xl">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Messages</h1>\n      <p className="text-muted text-sm mb-6">\n        Discute en prive avec les membres des camps que tu partages avec eux.\n      </p>\n\n      {contacts?.length === 0 && (\n        <div className="bg-surface border border-dashed border-border rounded-xl p-8 text-center">\n          <p className="text-muted text-sm">\n            Rejoins ou cree un camp pour pouvoir echanger en prive avec d\'autres membres.\n          </p>\n        </div>\n      )}\n\n      {contacts && contacts.length > 0 && (\n        <div className="flex gap-4 h-[calc(100vh-14rem)] md:h-[calc(100vh-12rem)]">\n          <div className="w-40 shrink-0 space-y-1 overflow-y-auto">\n            {contacts.map((c) => (\n              <button\n                key={c.id}\n                onClick={() => setSelected(c)}\n                className={`w-full text-left px-3 py-2 rounded-md text-sm ${\n                  selected?.id === c.id ? "bg-accent/15 text-accent" : "text-muted hover:bg-surface2"\n                }`}\n              >\n                {c.name}\n              </button>\n            ))}\n          </div>\n\n          <div className="flex-1 flex flex-col">\n            <div className="flex-1 overflow-y-auto bg-surface border border-border rounded-xl p-4 space-y-3 mb-3">\n              {messages === null && <p className="text-muted text-sm">Chargement...</p>}\n              {messages?.length === 0 && (\n                <p className="text-muted text-sm text-center py-8">Aucun message avec {selected?.name} pour l\'instant.</p>\n              )}\n              {messages?.map((m) => {\n                const isMine = m.senderId === user?.id;\n                return (\n                  <div key={m.id} className={`flex ${isMine ? "justify-end" : "justify-start"}`}>\n                    <div className={`max-w-[75%] rounded-lg px-3 py-2 ${isMine ? "bg-accent/20" : "bg-surface2"}`}>\n                      <p className="text-sm whitespace-pre-wrap break-words">{m.body}</p>\n                      <p className="text-[10px] text-muted mt-1">\n                        {new Date(m.createdAt).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}\n                      </p>\n                    </div>\n                  </div>\n                );\n              })}\n              <div ref={bottomRef} />\n            </div>\n\n            <form onSubmit={onSubmit} className="flex gap-2">\n              <input\n                value={text}\n                onChange={(e) => setText(e.target.value)}\n                placeholder={`Ecrire a ${selected?.name ?? ""}...`}\n                className="flex-1 bg-surface2 border border-border rounded-md px-3 py-2 text-sm"\n              />\n              <button\n                type="submit"\n                className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-2 text-sm"\n              >\n                Envoyer\n              </button>\n            </form>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n'
FILES['frontend/src/App.tsx'] = 'import { Navigate, Route, Routes } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "./context/AuthContext";\nimport Layout from "./components/Layout";\n\nimport Login from "./pages/Login";\nimport Register from "./pages/Register";\nimport Profile from "./pages/Profile";\nimport Dashboard from "./pages/Dashboard";\nimport CreateCamp from "./pages/CreateCamp";\nimport JoinCamp from "./pages/JoinCamp";\nimport CampDetail from "./pages/CampDetail";\nimport Today from "./pages/Today";\nimport Progress from "./pages/Progress";\nimport ExerciseRepository from "./pages/ExerciseRepository";\nimport CampChat from "./pages/CampChat";\nimport Messages from "./pages/Messages";\n\nfunction Private({ children }: { children: ReactNode }) {\n  const { user, loading } = useAuth();\n  if (loading) return <div className="min-h-screen flex items-center justify-center text-muted">Chargement...</div>;\n  if (!user) return <Navigate to="/connexion" replace />;\n  return <Layout>{children}</Layout>;\n}\n\nexport default function App() {\n  return (\n    <Routes>\n      <Route path="/connexion" element={<Login />} />\n      <Route path="/inscription" element={<Register />} />\n\n      <Route path="/aujourdhui" element={<Private><Today /></Private>} />\n      <Route path="/profil" element={<Private><Profile /></Private>} />\n      <Route path="/camps" element={<Private><Dashboard /></Private>} />\n      <Route path="/camps/creer" element={<Private><CreateCamp /></Private>} />\n      <Route path="/camps/rejoindre" element={<Private><JoinCamp /></Private>} />\n      <Route path="/camps/:id" element={<Private><CampDetail /></Private>} />\n      <Route path="/camps/:id/progression/:exerciseId" element={<Private><Progress /></Private>} />\n      <Route path="/exercices" element={<Private><ExerciseRepository /></Private>} />\n      <Route path="/camps/:id/discussion" element={<Private><CampChat /></Private>} />\n      <Route path="/messages" element={<Private><Messages /></Private>} />\n\n      <Route path="*" element={<Navigate to="/aujourdhui" replace />} />\n    </Routes>\n  );\n}\n'
FILES['frontend/src/components/Layout.tsx'] = 'import { NavLink, useNavigate } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "../context/AuthContext";\n\nconst navItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui" },\n  { to: "/camps", label: "Mes camps" },\n  { to: "/exercices", label: "Exercices" },\n  { to: "/messages", label: "Messages" },\n  { to: "/profil", label: "Profil" },\n];\n\nexport default function Layout({ children }: { children: ReactNode }) {\n  const { user, logout } = useAuth();\n  const navigate = useNavigate();\n\n  return (\n    <div className="min-h-screen flex flex-col md:flex-row">\n      <header className="md:w-64 md:min-h-screen border-b md:border-b-0 md:border-r border-border bg-surface flex md:flex-col justify-between">\n        <div className="p-6">\n          <div className="flex items-center gap-2 mb-8">\n            <span className="w-8 h-8 rounded bg-accent flex items-center justify-center font-display font-bold text-bg text-lg">\n              C\n            </span>\n            <span className="font-display text-lg tracking-wide uppercase">Camp</span>\n          </div>\n          <nav className="hidden md:flex md:flex-col gap-1">\n            {navItems.map((item) => (\n              <NavLink\n                key={item.to}\n                to={item.to}\n                className={({ isActive }) =>\n                  `px-3 py-2 rounded-md text-sm font-medium transition-colors ${\n                    isActive ? "bg-accent/15 text-accent" : "text-muted hover:text-text hover:bg-surface2"\n                  }`\n                }\n              >\n                {item.label}\n              </NavLink>\n            ))}\n          </nav>\n        </div>\n        <div className="p-6 hidden md:block">\n          {user && <p className="text-xs text-muted mb-2 truncate">{user.name}</p>}\n          <button\n            onClick={() => {\n              logout();\n              navigate("/connexion");\n            }}\n            className="text-sm text-muted hover:text-accent transition-colors"\n          >\n            Se deconnecter\n          </button>\n        </div>\n      </header>\n\n      <nav className="md:hidden flex justify-around bg-surface border-b border-border order-2">\n        {navItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 text-center py-3 text-xs font-medium ${isActive ? "text-accent" : "text-muted"}`\n            }\n          >\n            {item.label}\n          </NavLink>\n        ))}\n      </nav>\n\n      <main className="flex-1 p-5 md:p-10 max-w-4xl mx-auto w-full">{children}</main>\n    </div>\n  );\n}\n'

FILES_TO_DELETE = ['backend/src/routes/programs.ts']

for rel_path, content in FILES.items():
    p = pathlib.Path(rel_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')
    print('OK    ->', rel_path)

for rel_path in FILES_TO_DELETE:
    p = pathlib.Path(rel_path)
    if p.exists():
        p.unlink()
        print('SUPPR ->', rel_path)

print()
print('Termine :', 19, 'fichiers mis a jour,', 1, 'supprime(s).')